c(118, 1, T_CMOS, 'multi', 'CMOS ব্যাটারি নষ্ট: তারিখ-সময় ঠিক থাকে না ও বায়োসের অপশন সেভ হয় না। শক করে আর্থিং না থাকলে।', '৩৮')
c(119, 1, T_MON, 'multi', 'পাওয়ার অন কিন্তু ছবি নেই: ভিডিয়ো ক্যাবল মজবুতভাবে লাগানো ও ব্রাইটনেস-কনট্রাস্ট ঠিক করা। মনিটরের সফটওয়্যার বইয়ে নেই।', '৩৯')
c(120, 1, T_MON, 'multi', 'ছবি না এলে brightness ও contrast ঠিক করে দেখতে হবে। Windows মনিটরের সমাধানে নেই।', '৩৯', q='মনিটরের পাওয়ার চালু কিন্তু মনিটরে কোনো ছবি আসে না, কী সমস্যার কারণে হতে পারে?\ni. Brightness\nii. Windows\niii. Contrast\nনিচের কোনটি সঠিক?')

assert sorted(D) == sorted(mcq), set(mcq) ^ set(D)

topic_count = Counter(v['t'] for v in D.values())

def clean_q(s):
    s = s.replace('কি নির্ভর', 'কী নির্ভর')
    return s

cards = []
flags = []
for i, slide in enumerate(sorted(D)):
    m = mcq[slide]; v = D[slide]
    q = v['q'] or clean_q(m['question'])
    o = v['o'] or [m['options'][x] for x in L]
    key = m['answer']
    b = m['boards'] or ''
    if v['bnote']:
        b = (b + '; ' if b else '') + v['bnote']
    st = topic_count[v['t']] >= 2 or m['stars'] > 0
    cards.append(dict(id='2r%03d' % (i + 1), r=1, slide=slide, q=q, o=o, a=v['a'], key=key, b=b,
                      s=m['stars'], st=st, t=v['t'], k=v['k'], l=v['l'], p=v['p'], f=v['f'], dup=1))
    if v['f']:
        flags.append(dict(slide=slide, issue=v['f']))
    if L[v['a']] != key:
        assert v['f'], slide

json.dump(dict(cards=cards, flags=flags, topic_count=topic_count.most_common()),
          open(BASE + '/ch2_cards_tmp.json', 'w'), ensure_ascii=False, indent=1)
print(len(cards), Counter(c['k'] for c in cards))
for t, n in topic_count.most_common():
    print(n, t)
